    all_traces = [MOCK_TRACE] + benign
    labels = [1] + [0] * len(benign)

    dataset = build_dataset(all_traces, labels)
    assert len(dataset) == 6
    assert dataset[0].y.item() == 1
    for d in dataset[1:]:
        assert d.y.item() == 0
        assert d.x.shape[0] >= 1
